// === Tab: mySketch ===
var angle = 0; // Ubicacion
var radio = 50; 
var angularVelocity = 0; // Velocidad 
var angularAcceleration = 0.02; // Acelaeracion
var detuvo = false;
var cantidad; 

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100);
  noCursor();
  smooth();
}

function draw() {
  noStroke();
  fill(0,0.4);
  rectMode(CORNER);
  rect(0, 0, width, height);
  mover();
  show();
  cantidad = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 3, 30);
}

// Constant angular movement 
function mover() {
  if (!detuvo) {
    // Movimiento constante 
    angularVelocity += angularAcceleration;
    angularVelocity = constrain(angularVelocity, -0.02, 0.02); 
    angle += angularVelocity;
  }
}

function show() {
  for (var j = 1; j <= 1180; j+=(Math.max(0.001, Math.abs(radio)) || 1)) {
    for (var i = 0; i < cantidad; i++) {
      var posiciones = convertirVector(i, j + angle);
      push(); 
      stroke(map(j, 0, 1180, 0, 360), map(i, 0, 10, 0, 100), 100); 
      strokeWeight(1);
      //strokeWeight(j/(i+1));
      translate(width/2 + posiciones.x*i, height/2 + posiciones.y*i);
      rotate(-angle);

      rect(0, 0, radio/2, radio); 
      //arc(0, 0, radio/2, radio/2, radians(0), radians(45));
      pop();
    }
  }
  // Displaying cursos as a point 
  fill(255); 
  strokeWeight(5);
  stroke(255); 
  point((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
}

function convertirVector(r2,theta2) {
  // radio y angulo 
  var x = r2 * cos(theta2);
  var y = r2 * sin(theta2);

  return new p5.Vector(x, y);
}

function keyPressed() {
  detuvo = !detuvo; 
  //background(0);
}
